          <span
            key={i}
            ref={(el) => {
              cellsRef.current[i] = el;
            }}
            className={`inline-block whitespace-pre ${textClassName}`}
            style={{ padding: `${paddingY}px 0` }}
          >
            {' '}
          </span>
        ))}
      </div>

      {showTokens && (
        <span className='text-purple-700/70 tabular-nums' style={{ fontSize: fontSize * 0.85 }}>
          {tokens}k
        </span>
      )}
    </div>
  );
}

