declare function terminalFatal(error:unknown):void;
declare function registerTerminalCleanup(fn:()=>void):void;
// Owned, pausable timers and requestAnimationFrame handles. No wall-time catch-up.
export const scopes=new Set<ReturnType<typeof createScope>>();
const media=window.matchMedia('(prefers-reduced-motion: reduce)');
export const reduced=()=>media.matches;
let stopped=false;
export function createScope(){
 let disposed=false;const timers=new Set<any>();const frames=new Set<any>();
 const arm=(t:any)=>{if(disposed||stopped||document.hidden)return;t.start=performance.now();t.handle=setTimeout(()=>{t.handle=null;timers.delete(t);if(!disposed&&!stopped){try{t.fn()}catch(error){terminalFatal(error)}}},reduced()?0:t.left)};
 const frameArm=(f:any)=>{if(disposed||stopped||document.hidden)return;f.handle=requestAnimationFrame(ts=>{f.handle=null;frames.delete(f);if(!disposed&&!stopped){try{f.fn(ts)}catch(error){terminalFatal(error)}}})};
 const api={
  after(fn:()=>void,ms:number){if(disposed||stopped)return;const t={fn,left:ms,start:0,handle:null};timers.add(t);arm(t)},
  frame(fn:(ts:number)=>void){if(disposed||stopped)return;const f={fn,handle:null};frames.add(f);frameArm(f)},
  pause(){for(const t of timers)if(t.handle!==null){clearTimeout(t.handle);t.handle=null;t.left=Math.max(0,t.left-(performance.now()-t.start))}for(const f of frames)if(f.handle!==null){cancelAnimationFrame(f.handle);f.handle=null}},
  resume(){if(disposed)return;for(const t of timers)if(t.handle===null)arm(t);for(const f of frames)if(f.handle===null)frameArm(f)},
  dispose(){if(disposed)return;disposed=true;api.pause();timers.clear();frames.clear();scopes.delete(api)},
  stats(){return {timers:timers.size,frames:frames.size}}
 };scopes.add(api);return api;
}
function visibility(){document.documentElement.dataset.hidden=String(document.hidden);for(const s of scopes)document.hidden?s.pause():s.resume()}
function preference(){for(const s of scopes){s.pause();s.resume()}}
registerTerminalCleanup(disposeLifecycle);
try{document.addEventListener('visibilitychange',visibility);media.addEventListener('change',preference);visibility()}catch(error){disposeLifecycle();throw error}
export function disposeLifecycle(){stopped=true;for(const s of [...scopes])s.dispose();document.removeEventListener('visibilitychange',visibility);media.removeEventListener('change',preference)}

